2	
3	import org.junit.jupiter.api.Test;
4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	import tools.jackson.databind.JsonNode;
6	
7	/** audit-create: on successful create, an AUDIT log line carries the owner id, the
8	 * customerCode and the registrationDate. */
9	class AcceptanceTest extends AcceptanceBase {
10	
11		@Test
12		void coreLogsAuditOnCreate() throws Exception {
13			try (AuditLogCapture audit = new AuditLogCapture()) {
14				int id = createOwnerOk(ownerNode());
15				JsonNode o = fetchOwner(id);
16				assertTrue(audit.anyContains(String.valueOf(id),
17						o.get("customerCode").asText(), o.get("registrationDate").asText()));
18			}
19		}
20	}
