3	/**
4	 * Converts a telephone number to E.164 form. A leading {@code '+'} and country code are kept when
5	 * present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
6	 * from the national digits. Spaces, dashes and brackets are stripped. The result must have 8 to 15
7	 * digits after the {@code '+'}, otherwise it cannot form valid E.164.
8	 */
9	final class TelephoneE164 {
10	
11	    private TelephoneE164() {
12	    }
13	
14	    /**
15	     * Normalizes {@code raw} to E.164, throwing {@link InvalidTelephoneException} when it cannot.
16	     */
17	    static String normalize(String raw) throws InvalidTelephoneException {
18	        String e164 = normalizeOrNull(raw);
19	        if (e164 == null) {
20	            throw new InvalidTelephoneException(raw);
21	        }
22	        return e164;
23	    }
24	
25	    /**
26	     * Normalizes {@code raw} to E.164, returning {@code null} when it cannot form valid E.164.
27	     */
28	    static String normalizeOrNull(String raw) {
29	        if (raw == null) {
30	            return null;
31	        }
32	        // Strip spaces, dashes and brackets, keeping a leading '+' and the digits.
33	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
34	        String national;
35	        if (cleaned.startsWith("+")) {
36	            national = cleaned.substring(1);
37	            if (!national.matches("\\d+")) {
38	                return null;
39	            }
40	        }
41	        else {
42	            if (!cleaned.matches("\\d+")) {
43	                return null;
44	            }
45	            // No country code: assume +61 and drop a single leading '0' from the national digits.
46	            if (cleaned.startsWith("0")) {
47	                cleaned = cleaned.substring(1);
48	            }
49	            national = "61" + cleaned;
50	        }
51	        if (national.length() < 8 || national.length() > 15) {
52	            return null;
53	        }
54	        return "+" + national;
55	    }
56	}
