3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Derives an owner's {@code householdId}: a stable identifier shared by every owner with the same
10	 * last name and address (one household). The last name is normalized the same way as
11	 * {@link RejectDuplicateHousehold} (trim, collapse runs of whitespace to a single space, lower-case)
12	 * and the address in the normalized form ({@link AddressNormalizer}) — the same form the duplicate
13	 * check compares — before hashing, so owners created with {@code sharesHousehold} true, who by
14	 * definition match an existing owner's last name and address, derive the identical value. Computed as
15	 * the first 12 upper-case hex characters of SHA-256 over the normalized pair, so it is stable across
16	 * requests and needs no persisted column.
17	 */
18	public final class HouseholdId {
19	
20	    private HouseholdId() {
21	    }
22	
23	    public static String of(String lastName, String address) {
24	        String key = normalize(lastName) + "\n" + AddressNormalizer.normalize(address);
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest(key.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder hex = new StringBuilder(digest.length * 2);
29	            for (byte b : digest) {
30	                hex.append(String.format("%02x", b));
31	            }
32	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
33	        }
34	        catch (NoSuchAlgorithmException e) {
35	            throw new IllegalStateException("SHA-256 not available", e);
36	        }
37	    }
38	
39	    private static String normalize(String value) {
40	        if (value == null) {
41	            return "";
42	        }
43	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
45	}
