===== MissingOwnerFieldsException =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;

/**
 * Thrown by {@link RequireOwnerFields} when a create-owner request is missing or blank in any of the
 * mandatory fields. Handled globally by {@code MissingOwnerFieldsExceptionHandler}, which responds 400
 * with a JSON body whose {@code errors} array lists the offending field names.
 */
public class MissingOwnerFieldsException extends Exception {

    private final List<String> fields;

    public MissingOwnerFieldsException(List<String> fields) {
        super("Missing or blank required owner fields: " + fields);
        this.fields = List.copyOf(fields);
    }

    public List<String> getFields() {
        return this.fields;
    }
}
===== InvalidTelephoneException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link NormalizeTelephone} when a create-owner request's telephone cannot be normalized to
 * valid E.164 form (8 to 15 digits after the '+'). Handled globally by
 * {@code InvalidTelephoneExceptionHandler}, which responds 400.
 */
public class InvalidTelephoneException extends Exception {

    public InvalidTelephoneException(String telephone) {
        super("Telephone cannot be normalized to valid E.164 (8 to 15 digits after '+'): "
                + telephone);
    }
}
===== InvalidEmailException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link NormalizeEmail} when an owner request supplies an {@code email} that is not a
 * syntactically valid address. Handled globally by {@code InvalidEmailExceptionHandler}, which
 * responds 400.
 */
public class InvalidEmailException extends Exception {

    public InvalidEmailException(String email) {
        super("Email must be a syntactically valid address: " + email);
    }
}
===== DuplicateTelephoneException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link RejectDuplicateTelephone} when a create-owner request's normalized telephone is
 * already used by another owner. Handled globally by {@code DuplicateTelephoneExceptionHandler},
 * which responds 409.
 */
public class DuplicateTelephoneException extends Exception {

    public DuplicateTelephoneException(String telephone) {
        super("Telephone already in use by another owner: " + telephone);
    }
}
===== DuplicateHouseholdException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link RejectDuplicateHousehold} when a create-owner request has the same last name and
 * address (compared case-insensitively with collapsed whitespace) as an existing owner, and the
 * request did not set {@code sharesHousehold} true. Handled globally by
 * {@code DuplicateHouseholdExceptionHandler}, which responds 409.
 */
public class DuplicateHouseholdException extends Exception {

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with last name '" + lastName + "' already lives at address '" + address
                + "'; set sharesHousehold true to allow.");
    }
}
===== CityAtCapacityException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link RejectCityAtCapacity} when a create-owner request names a city that already
 * contains 50 or more owners. Handled globally by {@code CityAtCapacityExceptionHandler}, which
 * responds 409.
 */
public class CityAtCapacityException extends Exception {

    public CityAtCapacityException(String city, int limit) {
        super("City '" + city + "' already has " + limit + " or more owners and cannot accept another.");
    }
}
===== DailyLimitExceededException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link RejectOverDailyLimit} when 100 or more owners have already been created today
 * (by {@code registrationDate}). Handled globally by {@code DailyLimitExceededExceptionHandler},
 * which responds 429.
 */
public class DailyLimitExceededException extends Exception {

    public DailyLimitExceededException(int limit) {
        super("Daily owner creation limit of " + limit + " has been reached; try again tomorrow.");
    }
}
